export default function Dashboard() {
  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-purple-900 via-slate-900 to-indigo-900 text-white">

      <div className="bg-slate-800 p-10 rounded-2xl shadow-2xl text-center w-[400px]">

        <h1 className="text-4xl font-bold text-gradient mb-4">
          Welcome 🎉
        </h1>

        <p className="text-gray-300 mb-8">
          You are successfully logged in using Magic Link Authentication.
        </p>

        <button
          className="bg-gradient-to-r from-purple-500 to-cyan-400 px-6 py-3 rounded-lg font-semibold hover:scale-105 transition"
          onClick={() => {
            localStorage.removeItem("authToken");
            window.location.href = "/";
          }}
        >
          Log Out
        </button>

      </div>

    </div>
  );
}
